private fun error(condition: Boolean, reason: String) { if (condition) throw Fault(reason) }
    fun order(raw: String): Order {
        val n = raw.toLong()
        error(n < 1 || n > orders.size,"unknown order $raw")
        return orders[n.toInt()-1]
